    public static string Script(string setup, string command, string expression) =>
        "SET SAFETY OFF\nSET CPDIALOG OFF\nSET CENTURY ON\n" + setup
        + "\nresult='OK'\nTRY\n" + command
        + "\nresult=result+':'+TRANSFORM(_TALLY)\nCATCH TO ex\nresult='E'+TRANSFORM(ex.ErrorNo)\nENDTRY\n"
        + "SELECT t\nresult=result+'|'+TRANSFORM(RECCOUNT())+'|'\nSCAN\nresult=result+" + expression + "+';'\nENDSCAN";

    // DDL coverage is separate: these small, synthetic VFP9-created schemas exercise
    // import defaults/rules/autoinc without depending on microVFP's DDL subset.
    public static bool NeedsFixture(string setup) => setup.Contains("* VFP fixture") || setup.Contains("CREATE DATABASE") || setup.Contains("AUTOINC NEXTVALUE")
        || setup.Contains("(n I AUTOINC)") || setup.Contains("ALTER TABLE");

    public static string Arrange(string name, string setup, string directory, VfpSession session)
    {
        if (!NeedsFixture(setup)) return setup;
        string source = Path.Combine(Fixtures.VfpTestDir, "dataimport", name);
        foreach (string file in Directory.EnumerateFiles(source))
            File.Copy(file, Path.Combine(directory, Path.GetFileName(file)), true);
        if (setup.Contains("CREATE DATABASE")) session.OpenDatabase(Path.Combine(directory, "testdb.dbc"));
        session.Use("t");
        return string.Join("\n", setup.Split('\n').Where(line => !line.StartsWith("CREATE ")
            && !line.StartsWith("INSERT ") && !line.StartsWith("ALTER ") && !line.StartsWith("INDEX ")));
    }

    [Theory]
    [MemberData(nameof(Cases))]
    public void Import_MatchesCapturedVfp9(string name, string setup, string command, string expression, string expected)
    {
        using var dir = new MicroVfpTestSupport.TempDir("import");
        using var session = new VfpSession();
        session.OpenDirectory(dir.Path);
        using var interpreter = new VfpInterpreter(session);
        setup = Arrange(name, setup, dir.Path, session);
        interpreter.Execute(Script(setup, command, expression));
        Assert.True(expected == interpreter.EvalExpression("result").AsString, name + ": expected " + expected + "; actual " + interpreter.EvalExpression("result").AsString);
    }
}
